create extension if not exists pgcrypto;
do $$ begin create type public.user_role as enum ('founder','investor','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.verification_status as enum ('deferred','not_started','pending','approved','rejected'); exception when duplicate_object then null; end $$;
do $$ begin create type public.onboarding_status as enum ('not_started','in_progress','completed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.investor_type as enum ('individual','fund_manager'); exception when duplicate_object then null; end $$;
create table if not exists public.users (id uuid primary key references auth.users(id) on delete cascade,email text not null,role public.user_role not null,verification_status public.verification_status not null default 'deferred',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists users_email_lower_uidx on public.users(lower(email));
create table if not exists public.user_profiles (user_id uuid primary key references public.users(id) on delete cascade,legal_first_name text,legal_last_name text,country text,city text,timezone text,linkedin_url text,professional_title text,organization text,biography text,photo_path text,languages text[] not null default '{}',updated_at timestamptz not null default now());
create table if not exists public.investor_profiles (user_id uuid primary key references public.users(id) on delete cascade,investor_type public.investor_type not null default 'individual',investment_thesis text,familiar_markets text[] not null default '{}',experience text,risk_profile text,expertise_areas text[] not null default '{}',ask_me_about text,preferred_regions text[] not null default '{}',investment_stages text[] not null default '{}',preferred_ticket_size text,preferred_instruments text[] not null default '{}',investment_horizon text,investor_classification text,private_company_experience text,source_of_funds text,risk_acknowledged boolean not null default false,collaboration_preferences jsonb not null default '{}',onboarding_status public.onboarding_status not null default 'not_started',completed_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.founder_profiles (user_id uuid primary key references public.users(id) on delete cascade,onboarding_status public.onboarding_status not null default 'not_started',completed_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.startups (id uuid primary key default gen_random_uuid(),founder_user_id uuid not null references public.users(id) on delete cascade,legal_name text not null,display_name text,country text,sector text,website text,description text,founding_year integer,stage text,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists startups_founder_user_idx on public.startups(founder_user_id);
create table if not exists public.startup_documents (id uuid primary key default gen_random_uuid(),startup_id uuid not null references public.startups(id) on delete cascade,uploaded_by_user_id uuid not null references public.users(id) on delete cascade,document_type text not null,title text not null,storage_path text not null,created_at timestamptz not null default now());
create table if not exists public.onboarding_progress (user_id uuid primary key references public.users(id) on delete cascade,flow_type public.user_role not null,current_screen smallint not null default 0,completed_screens smallint[] not null default '{}',last_saved_at timestamptz not null default now());
create table if not exists public.agreement_acceptances (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,agreement_type text not null,agreement_version text not null,accepted boolean not null default true,signature_name text,signed_at timestamptz,accepted_at timestamptz not null default now(),unique(user_id,agreement_type,agreement_version));
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path=public as $$ declare requested_role public.user_role; begin requested_role := case when new.raw_user_meta_data->>'role'='founder' then 'founder'::public.user_role else 'investor'::public.user_role end; insert into public.users(id,email,role,verification_status) values(new.id,coalesce(new.email,''),requested_role,'deferred') on conflict(id) do nothing; insert into public.user_profiles(user_id) values(new.id) on conflict do nothing; if requested_role='investor' then insert into public.investor_profiles(user_id,onboarding_status) values(new.id,'in_progress') on conflict do nothing; else insert into public.founder_profiles(user_id,onboarding_status) values(new.id,'in_progress') on conflict do nothing; end if; insert into public.onboarding_progress(user_id,flow_type,current_screen) values(new.id,requested_role,0) on conflict do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_auth_user();
